/**
 * This protocol is used to connect to a KNX bus via an IP interface.
 */
public class KNXProtocol extends AbstractProtocol<KNXAgent, KNXAgentLink> implements ProtocolAssetImport {

    private static final Logger LOG = SyslogCategory.getLogger(PROTOCOL, KNXProtocol.class);
    public static final String PROTOCOL_DISPLAY_NAME = "KNX";

    protected KNXConnection connection;
    final protected Map<AttributeRef, Datapoint> attributeActionMap = new HashMap<>();
    final protected Map<AttributeRef, StateDP> attributeStatusMap = new HashMap<>();

    public KNXProtocol(KNXAgent agent) {
        super(agent);
    }

    @Override
    public String getProtocolName() {
        return PROTOCOL_DISPLAY_NAME;
    }

    @Override
    protected void doStart(Container container) throws Exception {

        boolean isNat = agent.isNATMode().orElse(false);
        boolean isRouting = agent.isRoutingMode().orElse(false);
        String gatewayAddress = agent.getHost().orElseThrow(() -> {
            String msg = "No KNX gateway IP address provided for protocol: " + this;
            LOG.info(msg);
            return new IllegalArgumentException(msg);
        });

        String bindAddress = agent.getBindHost().orElse(null);
        Integer gatewayPort = agent.getPort().orElse(3671);
        String messageSourceAddress = agent.getMessageSourceAddress().orElse("0.0.0");

        connection = new KNXConnection(gatewayAddress, bindAddress, gatewayPort, messageSourceAddress, isRouting, isNat);
        connection.addConnectionStatusConsumer(this::setConnectionStatus);
        connection.connect();
    }

    @Override
    protected void doStop(Container container) throws Exception {
        if (connection != null) {
            connection.removeConnectionStatusConsumer(this::setConnectionStatus);
            connection.disconnect();
        }
    }

    @Override
    protected void doLinkAttribute(String assetId, Attribute<?> attribute, KNXAgentLink agentLink) throws RuntimeException {
        final AttributeRef attributeRef = new AttributeRef(assetId, attribute.getName());

        // Check there is a META_KNX_DPT
        String dpt = getOrThrowAgentLinkProperty(agentLink.getDpt(), "DPT");

        Optional<String> statusGA = agentLink.getStatusGroupAddress();
        Optional<String> actionGA = agentLink.getActionGroupAddress();

        if (!statusGA.isPresent() && !actionGA.isPresent()) {
            LOG.warning("No status group address or action group address provided so nothing to do for protocol attribute: " + attributeRef);
            return;
        }

        // If this attribute relates to a read group then start monitoring that measurement and broadcast any changes to the value
        statusGA.ifPresent(groupAddress -> {
            try {
                addStatusDatapoint(attributeRef, groupAddress, dpt);
            } catch (KNXFormatException e) {
                LOG.severe("Give action group address is invalid for protocol attribute: " + attributeRef + " - " + e.getMessage());
            }
        });

        // If this attribute relates to an action then store it
        actionGA.ifPresent(groupAddress -> {
            try {
                addActionDatapoint(attributeRef, groupAddress, dpt);
            } catch (KNXFormatException e) {
                LOG.severe("Give action group address is invalid for protocol attribute: " + attributeRef + " - " + e.getMessage());
            }
        });
    }


    @Override
    protected void doUnlinkAttribute(String assetId, Attribute<?> attribute, KNXAgentLink agentLink) {
        final AttributeRef attributeRef = new AttributeRef(assetId, attribute.getName());

        // If this attribute is registered for status updates then un-subscribe it
        removeStatusDatapoint(attributeRef);

        // If this attribute has a stored action then remove it
        removeActionDatapoint(attributeRef);
    }

    @Override
    protected void doLinkedAttributeWrite(KNXAgentLink agentLink, AttributeEvent event, Object processedValue) {

        synchronized (attributeActionMap) {
            Datapoint datapoint = attributeActionMap.get(event.getRef());

            if (datapoint == null) {
                LOG.fine("Attribute isn't linked to a KNX datapoint so cannot process write: " + event);
                return;
            }

            connection.sendCommand(datapoint, event.getValue());

            // We assume KNX actuator will send new status on relevant status group address which will be picked up by listener and updates the state again later
            updateLinkedAttribute(event.getRef(), event.getValue());
        }
    }

    protected void addActionDatapoint(AttributeRef attributeRef, String groupAddress, String dpt) throws KNXFormatException {
        synchronized (attributeActionMap) {
            Datapoint datapoint = new CommandDP(new GroupAddress(groupAddress), attributeRef.getName());
            datapoint.setDPT(0, dpt);

            attributeActionMap.put(attributeRef, datapoint);
            LOG.info("Attribute registered for sending commands: " + attributeRef + " with datapoint: " + datapoint);
        }
    }

    protected void removeActionDatapoint(AttributeRef attributeRef) {
        synchronized (attributeActionMap) {
            attributeActionMap.remove(attributeRef);
        }
    }

    protected void addStatusDatapoint(AttributeRef attributeRef, String groupAddress, String dpt) throws KNXFormatException {
        synchronized (attributeStatusMap) {
            StateDP datapoint = new StateDP(new GroupAddress(groupAddress), attributeRef.getName(), 0, dpt);
            connection.addDatapointValueConsumer(datapoint, value -> handleKNXValueChange(attributeRef, value));

            attributeStatusMap.put(attributeRef, datapoint);
            LOG.info("Attribute registered for status updates: " + attributeRef + " with datapoint: " + datapoint);
        }
    }

    protected void handleKNXValueChange(AttributeRef attributeRef, Object value) {
        LOG.fine("KNX protocol received value '" + value + "' for : " + attributeRef);
        updateLinkedAttribute(attributeRef, value);
    }

    protected void removeStatusDatapoint(AttributeRef attributeRef) {
        synchronized (attributeStatusMap) {
            StateDP statusDP = attributeStatusMap.remove(attributeRef);
            if (statusDP != null) {
                connection.removeDatapointValueConsumer(statusDP);
            }
        }
    }

    @Override
    public String getProtocolInstanceUri() {
        return "knx://" + connection;
    }

    @Override
    public Future<Void> startAssetImport(byte[] fileData, Consumer<AssetTreeNode[]> assetConsumer) {
        return executorService.submit(() -> {
            ZipInputStream zin = null;

            try {
                boolean fileFound = false;
                zin = new ZipInputStream(new ByteArrayInputStream(fileData));
                ZipEntry zipEntry = zin.getNextEntry();
                while (zipEntry != null) {
                    if (zipEntry.getName().endsWith("/0.xml")) {
                        fileFound = true;
                        break;
                    }
                    zipEntry = zin.getNextEntry();
                }

                if (!fileFound) {
                    String msg = "Failed to find '0.xml' in project file";
                    LOG.info(msg);
                    throw new IllegalStateException(msg);
                }

                // Create a transform factory instance.
                TransformerFactory tfactory = new net.sf.saxon.TransformerFactoryImpl();

                // Create a transformer for the stylesheet.
                InputStream inputStream = KNXProtocol.class.getResourceAsStream("/org/openremote/agent/protocol/knx/ets_calimero_group_name.xsl");
                String xsd = IOUtils.toString(inputStream, StandardCharsets.UTF_8);
                xsd = xsd.trim().replaceFirst("^([\\W]+)<","<"); // Get weird behaviour sometimes without this
                LOG.warning(xsd);
                Transformer transformer = tfactory.newTransformer(new StreamSource(new StringReader(xsd)));

                // Set the URIResolver
                transformer.setURIResolver(new ETSFileURIResolver(fileData));

                // Transform the source XML
                String xml = IOUtils.toString(zin, StandardCharsets.UTF_8);
                xml = xml.trim().replaceFirst("^([\\W]+)<","<"); // Get weird behaviour sometimes without this
                LOG.warning(xml);
                StringWriter writer = new StringWriter();
                StringReader reader = new StringReader(xml);
                transformer.transform(new StreamSource(reader), new StreamResult(writer));
                xml = writer.toString();

                // we use a map of state-based data points and read from the transformed xml
                final DatapointMap<StateDP> datapoints = new DatapointMap<>();
                try (final XmlReader r = XmlInputFactory.newInstance().createXMLStreamReader(new StringReader(xml))) {
                    datapoints.load(r);
                } catch (final KNXMLException e) {
                    String msg = "Error loading parsed ETS file: " + e.getMessage();
                    LOG.warning(msg);
                    throw new IllegalStateException(msg, e);
                }

                Map<String, Asset<?>> createdAssets = new HashMap<>();
                for (StateDP dp : datapoints.getDatapoints()) {
                    if (dp.getName().endsWith("#A")) {
                        createAsset(dp, false, createdAssets);
                    } else if (dp.getName().endsWith("#S")) {
                        createAsset(dp, true, createdAssets);
                    } else if (dp.getName().endsWith("#SA") || dp.getName().endsWith("#AS")) {
                        createAsset(dp, false, createdAssets);
                        createAsset(dp, true, createdAssets);
                    } else {
                        LOG.info("Only group addresses ending on #A, #S, #AS or #SA will be imported. Ignoring: " + dp.getName());
                    }
                }

                assetConsumer.accept(createdAssets.values().stream().map(AssetTreeNode::new).toArray(AssetTreeNode[]::new));

            } catch (Exception e) {
                LOG.log(Level.WARNING, "ETS import error", e);
            } finally {
                if (zin != null) {
                    try {
                        zin.close();
                    } catch (IOException e) {
                        e.printStackTrace();
                    }
                }
            }
        }, null);
    }

    protected void createAsset(StateDP datapoint, boolean isStatusGA, Map<String, Asset<?>> createdAssets) {
        String name = datapoint.getName().substring(0, datapoint.getName().length()-3);
        String assetName = name.replaceAll(" -.*-", "");
        Asset<?> asset;

        if (createdAssets.containsKey(assetName)) {
            asset = createdAssets.get(assetName);
        } else {
            asset = new ThingAsset(assetName);
        }

        String attrName = assetName.replaceAll(" ", "");
        ValueDescriptor<?> type = TypeMapper.toAttributeType(datapoint);

        KNXAgentLink agentLink = new KNXAgentLink(
            agent.getId(),
            datapoint.getDPT(),
            !isStatusGA ? datapoint.getMainAddress().toString() : null,
            isStatusGA ? datapoint.getMainAddress().toString() : null);

        Attribute<?> attr = asset.getAttributes().get(attrName).orElse(new Attribute<>(attrName, type).addMeta(
                        new MetaItem<>(MetaItemType.LABEL, name),
                        new MetaItem<>(AGENT_LINK, agentLink)
        ));

        asset.getAttributes().addOrReplace(attr);

        createdAssets.put(assetName, asset);
    }

}

const _ = require('lodash');
const errors = require('@tryghost/errors');
const logging = require('@tryghost/logging');
const {
    canWelcomeEmailReplaceSignupPaidEmail
} = require('../../../lib/member-signup-contexts');
/** @typedef {import('../../../lib/member-signup-contexts').SignupContext} SignupContext */

/**
 * Handles `checkout.session.completed` webhook events
 *
 * The `checkout.session.completed` event is triggered when a customer completes a checkout session.
 *
 * It is triggered for the following scenarios:
 * - Subscription
 * - Donation
 * - Gift purchase
 * - Setup intent
 *
 * This service delegates the event to the appropriate handler based on the session mode and metadata.
 *
 * The `session` payload can be found here: https://docs.stripe.com/api/checkout/sessions/object
 */
module.exports = class CheckoutSessionEventService {
    /**
     * @param {object} deps
     * @param {import('../../stripe-api')} deps.api
     * @param {object} deps.memberRepository
     * @param {object} deps.donationRepository
     * @param {object} deps.giftService
     * @param {object} deps.staffServiceEmails
     * @param {function} deps.sendSignupEmail
     * @param {function} deps.isPaidWelcomeEmailActive
     */
    constructor(deps) {
        this.api = deps.api;
        this.deps = deps;
    }

    /**
     * Handles a `checkout.session.completed` event
     * Delegates to the appropriate handler based on the session mode and metadata
     * @param {import('stripe').Stripe.Checkout.Session} session
     */
    async handleEvent(session) {
        if (session.mode === 'setup') {
            await this.handleSetupEvent(session);
        }

        if (session.mode === 'subscription') {
            await this.handleSubscriptionEvent(session);
        }

        if (session.mode === 'payment' && session.metadata?.ghost_donation) {
            await this.handleDonationEvent(session);
        } else if (session.mode === 'payment' && session.metadata?.ghost_gift) {
            await this.handleGiftEvent(session);
        }
    }

    /**
     * Handles a `checkout.session.completed` event for a gift subscription purchase
     *
     * @param {import('stripe').Stripe.Checkout.Session} session
     */
    async handleGiftEvent(session) {
        await this.deps.giftService.recordPurchase({
            token: session.metadata?.gift_token,
            buyerEmail: session.customer_details?.email,
            stripeCustomerId: session.customer ?? null,
            tierId: session.metadata?.tier_id,
            cadence: session.metadata?.cadence,
            duration: session.metadata?.duration,
            currency: session.currency,
            amount: session.amount_total,
            stripeCheckoutSessionId: session.id,
            stripePaymentIntentId: session.payment_intent
        });
    }

    /**
     * Handles a `checkout.session.completed` event for a donation
     * @param {import('stripe').Stripe.Checkout.Session} session
     */
    async handleDonationEvent(session) {
        const donationField = session.custom_fields?.find(obj => obj?.key === 'donation_message');
        const donationMessage = donationField?.text?.value ? donationField.text.value : null;
        const amount = session.amount_total;
        const currency = session.currency;

        const memberRepository = this.deps.memberRepository;
        const member = session.customer ? (await memberRepository.get({customer_id: session.customer})) : null;

        const {DonationPaymentEvent} = require('../../../donations/donation-payment-event');
        const data = DonationPaymentEvent.create({
            name: member?.get('name') ?? session.customer_details.name,
            email: member?.get('email') ?? session.customer_details.email,
            memberId: member?.id ?? null,
            amount,
            currency,
            donationMessage,
            attributionId: session.metadata?.attribution_id ?? null,
            attributionUrl: session.metadata?.attribution_url ?? null,
            attributionType: session.metadata?.attribution_type ?? null,
            referrerSource: session.metadata?.referrer_source ?? null,
            referrerMedium: session.metadata?.referrer_medium ?? null,
            referrerUrl: session.metadata?.referrer_url ?? null,
            utmSource: session.metadata?.utm_source ?? null,
            utmMedium: session.metadata?.utm_medium ?? null,
            utmCampaign: session.metadata?.utm_campaign ?? null,
            utmTerm: session.metadata?.utm_term ?? null,
            utmContent: session.metadata?.utm_content ?? null
        });

        const donationRepository = this.deps.donationRepository;
        await donationRepository.save(data);

        const staffServiceEmails = this.deps.staffServiceEmails;
        await staffServiceEmails.notifyDonationReceived({donationPaymentEvent: data});
    }

    /**
     * Handles a `checkout.session.completed` event for a setup intent
     *
     * This is used when a customer adds or changes their payment method outside
     * of the normal subscription flow.
     * @param {import('stripe').Stripe.Checkout.Session} session
     */
    async handleSetupEvent(session) {
        const setupIntent = await this.api.getSetupIntent(session.setup_intent);

        const memberRepository = this.deps.memberRepository;
        const member = await memberRepository.get({
            customer_id: setupIntent.metadata.customer_id
        });

        if (!member) {
            return;
        }

        await this.api.attachPaymentMethodToCustomer(
            setupIntent.metadata.customer_id,
            setupIntent.payment_method
        );

        if (setupIntent.metadata.subscription_id) {
            const updatedSubscription = await this.api.updateSubscriptionDefaultPaymentMethod(
                setupIntent.metadata.subscription_id,
                setupIntent.payment_method
            );
            try {
                await memberRepository.linkSubscription({
                    id: member.id,
                    subscription: updatedSubscription
                });
            } catch (err) {
                if (err.code !== 'ER_DUP_ENTRY' && err.code !== 'SQLITE_CONSTRAINT') {
                    throw err;
                }
                throw new errors.ConflictError({
                    err
                });
            }
            return;
        }

        const subscriptions = await member.related('stripeSubscriptions').fetch();
        const activeSubscriptions = subscriptions.models.filter(subscription => ['active', 'trialing', 'unpaid', 'past_due'].includes(subscription.get('status'))
        );

        for (const subscription of activeSubscriptions) {
            if (subscription.get('customer_id') === setupIntent.metadata.customer_id) {
                const updatedSubscription = await this.api.updateSubscriptionDefaultPaymentMethod(
                    subscription.get('subscription_id'),
                    setupIntent.payment_method
                );
                try {
                    await memberRepository.linkSubscription({
                        id: member.id,
                        subscription: updatedSubscription
                    });
                } catch (err) {
                    if (err.code !== 'ER_DUP_ENTRY' && err.code !== 'SQLITE_CONSTRAINT') {
                        throw err;
                    }
                    throw new errors.ConflictError({
                        err
                    });
                }
            }
        }
    }

    /**
     * Handles a `checkout.session.completed` event for a subscription
     * @param {import('stripe').Stripe.Checkout.Session} session
     */
    async handleSubscriptionEvent(session) {
        const customer = await this.api.getCustomer(session.customer, {
            expand: ['subscriptions.data.default_payment_method']
        });

        const memberRepository = this.deps.memberRepository;

        let member = await memberRepository.get({
            email: customer.email
        });

        const checkoutType = _.get(session, 'metadata.checkoutType');

        if (!member) {
            const metadataName = _.get(session, 'metadata.name');
            const metadataNewsletters = _.get(session, 'metadata.newsletters');
            const attribution = {
                id: session.metadata?.attribution_id ?? null,
                url: session.metadata?.attribution_url ?? null,
                type: session.metadata?.attribution_type ?? null,
                referrerSource: session.metadata?.referrer_source ?? null,
                referrerMedium: session.metadata?.referrer_medium ?? null,
                referrerUrl: session.metadata?.referrer_url ?? null
            };

            const payerName = _.get(customer, 'subscriptions.data[0].default_payment_method.billing_details.name');
            const name = metadataName || payerName || null;

            const memberData = {email: customer.email, name, attribution};
            if (metadataNewsletters) {
                try {
                    memberData.newsletters = JSON.parse(metadataNewsletters);
                } catch (e) {
                    logging.error(`Ignoring invalid newsletters data - ${metadataNewsletters}.`);
                }
            }

            const offerId = session.metadata?.offer;
            const memberDataWithStripeCustomer = {
                ...memberData,
                stripeCustomer: customer,
                offerId
            };
            member = await memberRepository.create(memberDataWithStripeCustomer);
        } else {
            const payerName = _.get(customer, 'subscriptions.data[0].default_payment_method.billing_details.name');
            const attribution = {
                id: session.metadata?.attribution_id ?? null,
                url: session.metadata?.attribution_url ?? null,
                type: session.metadata?.attribution_type ?? null,
                referrerSource: session.metadata?.referrer_source ?? null,
                referrerMedium: session.metadata?.referrer_medium ?? null,
                referrerUrl: session.metadata?.referrer_url ?? null
            };

            if (payerName && !member.get('name')) {
                await memberRepository.update({name: payerName}, {id: member.get('id')});
            }

            await memberRepository.upsertCustomer({
                customer_id: customer.id,
                member_id: member.id,
                name: customer.name,
                email: customer.email
            });

            for (const subscription of customer.subscriptions.data) {
                try {
                    const offerId = session.metadata?.offer;

                    await memberRepository.linkSubscription({
                        id: member.id,
                        subscription,
                        offerId,
                        attribution
                    });
                } catch (err) {
                    if (err.code !== 'ER_DUP_ENTRY' && err.code !== 'SQLITE_CONSTRAINT') {
                        throw err;
                    }
                    throw new errors.ConflictError({
                        err
                    });
                }
            }

            // If member is now paid, remove any complimentary access
            const updatedMember = await memberRepository.get({id: member.id});
            if (updatedMember && updatedMember.get('status') === 'paid') {
                await memberRepository.removeComplimentarySubscription({id: member.id});
            }
        }

        if (checkoutType !== 'upgrade') {
            const ghostSignupContext = /** @type {SignupContext | undefined} */ (session.metadata?.ghostSignupContext);
            const shouldSkipSignupEmailWhenWelcomeEmailActive = canWelcomeEmailReplaceSignupPaidEmail(ghostSignupContext);

            if (shouldSkipSignupEmailWhenWelcomeEmailActive) {
                const isPaidWelcomeEmailActive = await this.deps.isPaidWelcomeEmailActive();
                if (!isPaidWelcomeEmailActive) {
                    this.deps.sendSignupEmail(customer.email);
                }
            } else {
                // Direct checkout flows do not have a pre-checkout sign-in path.
                this.deps.sendSignupEmail(customer.email);
            }
        }
    }
};

package scalers

import (
	"context"
	"database/sql"
	"fmt"
	"regexp"
	"strings"
	"time"

	"github.com/Azure/azure-sdk-for-go/sdk/azcore"
	"github.com/Azure/azure-sdk-for-go/sdk/azcore/policy"
	"github.com/Azure/azure-sdk-for-go/sdk/azidentity"
	"github.com/go-logr/logr"
	_ "github.com/jackc/pgx/v5/stdlib" // PostgreSQL drive required for this scaler
	v2 "k8s.io/api/autoscaling/v2"
	"k8s.io/metrics/pkg/apis/external_metrics"

	kedav1alpha1 "github.com/kedacore/keda/v2/apis/keda/v1alpha1"
	"github.com/kedacore/keda/v2/pkg/scalers/azure"
	"github.com/kedacore/keda/v2/pkg/scalers/scalersconfig"
	kedautil "github.com/kedacore/keda/v2/pkg/util"
)

const (
	// Azure AD resource ID for Azure Database for PostgreSQL is https://ossrdbms-aad.database.windows.net
	// https://learn.microsoft.com/en-us/azure/postgresql/single-server/how-to-connect-with-managed-identity
	azureDatabasePostgresResource = "https://ossrdbms-aad.database.windows.net/.default"
)

var (
	passwordConnPattern = regexp.MustCompile(`%PASSWORD%`)
)

type postgreSQLScaler struct {
	metricType  v2.MetricTargetType
	metadata    *postgreSQLMetadata
	connection  *sql.DB
	podIdentity kedav1alpha1.AuthPodIdentity
	logger      logr.Logger
}

type postgreSQLMetadata struct {
	TargetQueryValue           float64 `keda:"name=targetQueryValue,           order=triggerMetadata, optional"`
	ActivationTargetQueryValue float64 `keda:"name=activationTargetQueryValue, order=triggerMetadata, optional"`
	Connection                 string  `keda:"name=connection,                 order=authParams;resolvedEnv, optional"`
	Query                      string  `keda:"name=query,                      order=triggerMetadata"`
	triggerIndex               int
	azureAuthContext           azureAuthContext

	Host     string `keda:"name=host,     order=authParams;triggerMetadata, optional"`
	Port     string `keda:"name=port,     order=authParams;triggerMetadata, optional"`
	UserName string `keda:"name=userName, order=authParams;triggerMetadata, optional"`
	DBName   string `keda:"name=dbName,   order=authParams;triggerMetadata, optional"`
	SslMode  string `keda:"name=sslmode,  order=authParams;triggerMetadata, optional"`

	Password string `keda:"name=password, order=authParams;resolvedEnv, optional"`
}

func (p *postgreSQLMetadata) Validate() error {
	if p.Connection == "" {
		if p.Host == "" {
			return fmt.Errorf("no host given")
		}

		if p.Port == "" {
			return fmt.Errorf("no port given")
		}

		if p.UserName == "" {
			return fmt.Errorf("no userName given")
		}

		if p.DBName == "" {
			return fmt.Errorf("no dbName given")
		}

		if p.SslMode == "" {
			return fmt.Errorf("no sslmode given")
		}
	}

	return nil
}

type azureAuthContext struct {
	cred  *azidentity.ChainedTokenCredential
	token *azcore.AccessToken
}

// NewPostgreSQLScaler creates a new postgreSQL scaler
func NewPostgreSQLScaler(ctx context.Context, config *scalersconfig.ScalerConfig) (Scaler, error) {
	metricType, err := GetMetricTargetType(config)
	if err != nil {
		return nil, fmt.Errorf("error getting scaler metric type: %w", err)
	}

	logger := InitializeLogger(config, "postgresql_scaler")

	meta, podIdentity, err := parsePostgreSQLMetadata(logger, config)
	if err != nil {
		return nil, fmt.Errorf("error parsing postgreSQL metadata: %w", err)
	}

	conn, err := getConnection(ctx, meta, podIdentity, logger)
	if err != nil {
		return nil, fmt.Errorf("error establishing postgreSQL connection: %w", err)
	}
	return &postgreSQLScaler{
		metricType:  metricType,
		metadata:    meta,
		connection:  conn,
		podIdentity: podIdentity,
		logger:      logger,
	}, nil
}

func parsePostgreSQLMetadata(logger logr.Logger, config *scalersconfig.ScalerConfig) (*postgreSQLMetadata, kedav1alpha1.AuthPodIdentity, error) {
	meta := &postgreSQLMetadata{}
	authPodIdentity := kedav1alpha1.AuthPodIdentity{}
	meta.triggerIndex = config.TriggerIndex
	if err := config.TypedConfig(meta); err != nil {
		return nil, authPodIdentity, fmt.Errorf("error parsing postgresql metadata: %w", err)
	}

	if !config.AsMetricSource && meta.TargetQueryValue == 0 {
		return nil, authPodIdentity, fmt.Errorf("no targetQueryValue given")
	}

	switch config.PodIdentity.Provider {
	case "", kedav1alpha1.PodIdentityProviderNone:
		if meta.Connection == "" {
			params := buildConnArray(meta)
			params = append(params, "password="+escapePostgreConnectionParameter(meta.Password))
			meta.Connection = strings.Join(params, " ")
		}
	case kedav1alpha1.PodIdentityProviderAzureWorkload:
		params := buildConnArray(meta)

		cred, err := azure.NewChainedCredential(logger, config.PodIdentity)
		if err != nil {
			return nil, authPodIdentity, err
		}
		meta.azureAuthContext.cred = cred
		authPodIdentity = kedav1alpha1.AuthPodIdentity{Provider: config.PodIdentity.Provider}

		params = append(params, "%PASSWORD%")
		meta.Connection = strings.Join(params, " ")
	}
	meta.triggerIndex = config.TriggerIndex

	return meta, authPodIdentity, nil
}

func buildConnArray(meta *postgreSQLMetadata) []string {
	var params []string
	params = append(params, "host="+escapePostgreConnectionParameter(meta.Host))
	params = append(params, "port="+escapePostgreConnectionParameter(meta.Port))
	params = append(params, "user="+escapePostgreConnectionParameter(meta.UserName))
	params = append(params, "dbname="+escapePostgreConnectionParameter(meta.DBName))
	params = append(params, "sslmode="+escapePostgreConnectionParameter(meta.SslMode))

	return params
}

func getConnection(ctx context.Context, meta *postgreSQLMetadata, podIdentity kedav1alpha1.AuthPodIdentity, logger logr.Logger) (*sql.DB, error) {
	connectionString := meta.Connection

	if podIdentity.Provider == kedav1alpha1.PodIdentityProviderAzureWorkload {
		accessToken, err := getAzureAccessToken(ctx, meta, azureDatabasePostgresResource)
		if err != nil {
			return nil, err
		}
		newPasswordField := "password=" + escapePostgreConnectionParameter(accessToken)
		connectionString = passwordConnPattern.ReplaceAllString(meta.Connection, newPasswordField)
	}

	db, err := sql.Open("pgx", connectionString)
	if err != nil {
		logger.Error(err, fmt.Sprintf("Found error opening postgreSQL: %s", err))
		return nil, err
	}
	err = db.Ping()
	if err != nil {
		logger.Error(err, fmt.Sprintf("Found error pinging postgreSQL: %s", err))
		return nil, err
	}
	return db, nil
}

// Close disposes of postgres connections
func (s *postgreSQLScaler) Close(context.Context) error {
	err := s.connection.Close()
	if err != nil {
		s.logger.Error(err, "Error closing postgreSQL connection")
		return err
	}
	return nil
}

func (s *postgreSQLScaler) getActiveNumber(ctx context.Context) (float64, error) {
	var id float64

	if s.podIdentity.Provider == kedav1alpha1.PodIdentityProviderAzureWorkload {
		if s.metadata.azureAuthContext.token.ExpiresOn.Before(time.Now()) {
			s.logger.Info("The Azure Access Token expired, retrieving a new Azure Access Token and instantiating a new Postgres connection object.")
			s.connection.Close()
			newConnection, err := getConnection(ctx, s.metadata, s.podIdentity, s.logger)
			if err != nil {
				return 0, fmt.Errorf("error establishing postgreSQL connection: %w", err)
			}
			s.connection = newConnection
		}
	}

	err := s.connection.QueryRowContext(ctx, s.metadata.Query).Scan(&id)
	if err != nil {
		s.logger.Error(err, fmt.Sprintf("could not query postgreSQL: %s", err))
		return 0, fmt.Errorf("could not query postgreSQL: %w", err)
	}
	return id, nil
}

// GetMetricSpecForScaling returns the MetricSpec for the Horizontal Pod Autoscaler
func (s *postgreSQLScaler) GetMetricSpecForScaling(context.Context) []v2.MetricSpec {
	externalMetric := &v2.ExternalMetricSource{
		Metric: v2.MetricIdentifier{
			Name: GenerateMetricNameWithIndex(s.metadata.triggerIndex, kedautil.NormalizeString("postgresql")),
		},
		Target: GetMetricTargetMili(s.metricType, s.metadata.TargetQueryValue),
	}
	metricSpec := v2.MetricSpec{
		External: externalMetric, Type: externalMetricType,
	}
	return []v2.MetricSpec{metricSpec}
}

// GetMetricsAndActivity returns value for a supported metric and an error if there is a problem getting the metric
func (s *postgreSQLScaler) GetMetricsAndActivity(ctx context.Context, metricName string) ([]external_metrics.ExternalMetricValue, bool, error) {
	num, err := s.getActiveNumber(ctx)
	if err != nil {
		return []external_metrics.ExternalMetricValue{}, false, fmt.Errorf("error inspecting postgreSQL: %w", err)
	}

	metric := GenerateMetricInMili(metricName, num)

	return []external_metrics.ExternalMetricValue{metric}, num > s.metadata.ActivationTargetQueryValue, nil
}

func escapePostgreConnectionParameter(str string) string {
	if !strings.Contains(str, " ") {
		return str
	}

	str = strings.ReplaceAll(str, "'", "\\'")
	return fmt.Sprintf("'%s'", str)
}

func getAzureAccessToken(ctx context.Context, metadata *postgreSQLMetadata, scope string) (string, error) {
	accessToken, err := metadata.azureAuthContext.cred.GetToken(ctx, policy.TokenRequestOptions{
		Scopes: []string{
			scope,
		},
	})
	if err != nil {
		return "", err
	}

	metadata.azureAuthContext.token = &accessToken

	return metadata.azureAuthContext.token.Token, nil
}

